"const mergeBillItems = (items) => {
  const merged = [];
  items.forEach(item => {
    const existing = merged.find(m => 
      m.id === item.id &&
      (m.priceLabel || '') === (item.priceLabel || '') &&
      !!m.isComplementary === !!item.isComplementary &&
      JSON.stringify(m.modifiers || []) === JSON.stringify(item.modifiers || [])
    );
    if (existing) {
      existing.quantity = (parseFloat(existing.quantity) || 0) + (parseFloat(item.quantity) || 0);
      if (existing.qty !== undefined) {
        existing.qty = existing.quantity;
      }
    } else {
      merged.push({ ...item });
    }
  });
  return merged;
};

